// console.log because n8n forwards only that to container stdout.
// Two records, on purpose. The log line survives even if Convex is what is down;
// the write-back is what makes the failure visible to admins in the app.
const { execution, workflow } = $json;
const node = execution?.lastNodeExecuted ?? 'unknown node';
// For a failed sub-workflow, the real cause is in description; message is generic.
const message = execution?.error?.description ?? execution?.error?.message ?? 'unknown error';
const id = execution?.id ?? String(Date.now());
console.log(JSON.stringify({ channel: 'lendloop-workflow-failure', workflow: workflow?.name, executionId: id, node, message }));
// Forged webhooks are unauthenticated, so they share one row per minute instead of one
// row each: a flood cannot fill the admin log. The log line above still records every one.
const key = node === 'Rejected' ? `error:rejected:${new Date().toISOString().slice(0, 16)}` : `error:${id}`;
return {
  method: 'POST',
  path: '/n8n/activity',
  body: JSON.stringify({
    idempotencyKey: key,
    kind: 'workflow_error',
    status: 'failed',
    detail: `${workflow?.name} (execution ${id}) failed at "${node}": ${message}`.slice(0, 480),
  }),
};
